#!/usr/bin/env bash
# ============================================================================
# VideoMind rebuild, Part 2: app shell and design system
# ============================================================================
# FOR THE rebuild BRANCH ONLY. It refuses to run on main.
#
# The first build looked like an edit bay: near black, a red accent, a
# serif for headings, a monospace face for labels, a bar across the top.
# The brief asks for a quiet media workspace with the library first.
#
# After this part:
#   * every workspace page sits in one shell: a sidebar on wide screens,
#     a top bar with a slide in menu on phones
#   * the sidebar follows the structure in the brief. Pages that are not
#     built yet are listed, greyed out and marked "Soon" (one constant,
#     SHOW_PLANNED in AppShell.tsx, hides them)
#   * one theme, set in one place (globals.css + tailwind.config.ts):
#     graphite surfaces, one typeface, white for the main action, yellow
#     only for "where you are", green for done, red for failed
#   * Home is the library at a glance, not a sales page
#   * library cards show each video's chapters and a ruler cut at the
#     chapter boundaries, until real thumbnails exist
#   * empty and blocked states say what is going on and offer the next step
#   * the transcript no longer scrolls the page. Following the video
#     scrolls only the transcript, and stops when the reader scrolls
#   * the sidebar shows whether the Shelby network answers right now
#
#   FRONTEND  3 new files, 27 changed, 1 removed (the old top bar).
#   BACKEND   no changes. No new packages. No lockfile changes.
#
#   ./vm_shell.sh            apply (needs Parts 1b and 1c on the branch)
#   ./vm_shell.sh --force    apply even if local files differ from GitHub
#   ./vm_shell.sh --revert   restore everything from the latest backup
#
# Run from the repo root (dir containing backend/ and frontend/).
# ============================================================================
set -euo pipefail

