grep -q "$MARKER" "$TMPD/a0"                    || die "AppShell.tsx payload missing marker. Aborting."
grep -q "$MARKER" "$TMPD/m5"                   || die "globals.css payload missing marker. Aborting."
grep -q 'confirmVideo' "$TMPD/m19"              || die "UploadZone.tsx payload lost the upload flow. Aborting."
grep -q 'useUploadBlobs' "$TMPD/m19"            || die "UploadZone.tsx payload lost the Shelby upload. Aborting."
grep -q 'armSignIn' "$TMPD/m16"                 || die "WalletButton.tsx payload lost sign in. Aborting."
grep -q 'retryVideoJob' "$TMPD/m22"             || die "ProcessingStatus.tsx payload lost the retry. Aborting."
grep -q 'AppProviders' "$TMPD/m6"              || die "layout.tsx payload lost the providers. Aborting."
if grep -q 'scrollIntoView' "$TMPD/m23"; then die "TranscriptPanel.tsx payload still scrolls the page. Aborting."; fi
say "30 payloads decoded and verified."

# ---- backups ----
mkdir -p "$BAKDIR/$STAMP"
for f in "${MOD[@]}" "${DEL[@]}"; do cp "$f" "$BAKDIR/$STAMP/$(bname "$f")"; done
for f in "${ADD[@]}"; do if [ -f "$f" ]; then cp "$f" "$BAKDIR/$STAMP/$(bname "$f")"; fi; done
say "Backups saved to $BAKDIR/$STAMP/"

rollback() {
  restore_from "$BAKDIR/$STAMP"
  die "$1 All files restored from $BAKDIR/$STAMP."
}

# ---- write ----
i=0; for f in "${ADD[@]}"; do mkdir -p "$(dirname "$f")"; cp "$TMPD/a$i" "$f" || rollback "Could not write $f."; i=$((i+1)); done
i=0; for f in "${MOD[@]}"; do cp "$TMPD/m$i" "$f" || rollback "Could not write $f."; i=$((i+1)); done
for f in "${DEL[@]}"; do rm -f "$f"; done

i=0; for f in "${ADD[@]}"; do [ "$(sha "$f")" = "${NEW_ADD[$i]}" ] || rollback "$f write verify failed."; i=$((i+1)); done
i=0; for f in "${MOD[@]}"; do [ "$(sha "$f")" = "${NEW_MOD[$i]}" ] || rollback "$f write verify failed."; i=$((i+1)); done
for f in "${DEL[@]}"; do [ ! -f "$f" ] || rollback "Could not remove $f."; done

say "Applied the app shell and design system (rebuild Part 2)."
say "Verify before pushing:"
say "  cd frontend && npx tsc --noEmit && npm run build"
say "Undo: ./vm_shell.sh --revert"
